package com.prasanth.vitalguard.model;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="vital_readings") public class VitalReading{
@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String patientName; private int heartRate; private double spo2; private double temperature; private int systolic; private int diastolic; private String riskLevel; private String alertMessage; private LocalDateTime recordedAt;
@PrePersist void timestamp(){if(recordedAt==null)recordedAt=LocalDateTime.now();}
public Long getId(){return id;} public String getPatientName(){return patientName;} public void setPatientName(String v){patientName=v;} public int getHeartRate(){return heartRate;} public void setHeartRate(int v){heartRate=v;} public double getSpo2(){return spo2;} public void setSpo2(double v){spo2=v;} public double getTemperature(){return temperature;} public void setTemperature(double v){temperature=v;} public int getSystolic(){return systolic;} public void setSystolic(int v){systolic=v;} public int getDiastolic(){return diastolic;} public void setDiastolic(int v){diastolic=v;} public String getRiskLevel(){return riskLevel;} public void setRiskLevel(String v){riskLevel=v;} public String getAlertMessage(){return alertMessage;} public void setAlertMessage(String v){alertMessage=v;} public LocalDateTime getRecordedAt(){return recordedAt;}}
